package com.bank.jvm.epsilon;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class InterestAllocationProbe {
    private static final Logger log = Logger.getLogger(InterestAllocationProbe.class.getName());

    public static void main(String[] args) {
        GrowthReporter reporter = new GrowthReporter();
        log.info("Bank: National Bank of India — Epsilon allocation-rate probe");
        log.warning("Running under EPSILON: no GC. Heap only grows until OOM. For measurement only.");

        InterestCalculation calc = new InterestCalculation();
        // We INTENTIONALLY retain results so nothing could be freed even by a real GC;
        // under Epsilon this makes heap growth a clean straight line to measure.
        List<BigDecimal> retained = new ArrayList<>();

        long account = 0;
        try {
            while (true) {
                BigDecimal interest = calc.calculateFor("SAV" + (2000 + account),
                        new BigDecimal("1000000"), 7);
                retained.add(interest);
                account++;
                if (account % 100_000 == 0) reporter.report(account);
            }
        } catch (OutOfMemoryError oom) {
            log.severe(() -> "OOM after processing " + account + " accounts — heap full, "
                    + "no GC reclaimed anything (expected under Epsilon)");
            reporter.summarize(account);
        }
    }
}

// ─── Would be in InterestCalculation.java in a real project ───
class InterestCalculation {
    // Each call allocates intermediate objects; Epsilon never reclaims them.
    BigDecimal calculateFor(String accountId, BigDecimal principal, int ratePercent) {
        BigDecimal rate = new BigDecimal(ratePercent).movePointLeft(2);
        BigDecimal annual = principal.multiply(rate);
        BigDecimal monthly = annual.divide(new BigDecimal(12), 2, BigDecimal.ROUND_HALF_UP);
        // Build a small per-account label so each call allocates a String too.
        String label = accountId + ":" + monthly.toPlainString();
        return monthly.add(new BigDecimal(label.length()));
    }
}
