package com.bank.jvm.epsilon;

import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.util.logging.Logger;

class GrowthReporter {
    private static final Logger log = Logger.getLogger(GrowthReporter.class.getName());
    private final MemoryMXBean memoryBean = ManagementFactory.getMemoryMXBean();

    void report(long accounts) {
        long usedMb = memoryBean.getHeapMemoryUsage().getUsed() / (1024 * 1024);
        log.info(() -> "Processed " + accounts + " accounts, heap used=" + usedMb
                + "MB (monotonic — no GC under Epsilon)");
    }

    void summarize(long accounts) {
        long maxMb = memoryBean.getHeapMemoryUsage().getMax() / (1024 * 1024);
        if (accounts == 0) { log.info("No accounts processed"); return; }
        double bytesPerAccount = (maxMb * 1024.0 * 1024.0) / accounts;
        log.info(() -> String.format("Allocation analysis: ~%.0f bytes/account "
                + "(heap %dMB / %d accounts)", bytesPerAccount, maxMb, accounts));
    }
}
